{
  "per_column": [
    {
      "name": "negative_word_count",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Counting negative lexicon terms is a strong, directly relevant signal for predicting negative satisfaction. Values track source text plausibly (e.g., 'crap', 'terrible', 'worst' yielding 4 in row 2; 0 for the positive review 4)."
    },
    {
      "name": "exclamation_count",
      "analytical_usefulness": 0.55,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "Punctuation-based intensity proxy; not sentiment-directional but can capture emphatic tone, giving some modeling leverage. Values are mechanically verifiable and match source (8 exclamations for the '!!!! SPOILERS !!!!' row)."
    },
    {
      "name": "caps_word_count",
      "analytical_usefulness": 0.5,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "All-caps word count is a generic emphasis/shouting proxy—weakly tied to satisfaction and somewhat borderline on the 'raw text feature' concern, but still a distinct axis. Values are consistent with source text."
    },
    {
      "name": "negation_intensifier_count",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.75,
      "hallucination_observed": false,
      "rationale": "Negations/intensifiers are analytically meaningful for sentiment polarity and strength. Grounding is reasonable but noisier: row 1 gets 8 and row 4 (positive) gets 3, suggesting it captures generic intensifiers ('really', 'plenty') that don't cleanly separate negativity, though values remain derivable from text."
    }
  ],
  "analytical_usefulness": 0.68,
  "source_groundedness": 0.88,
  "rationale": "The added columns provide several distinct, query-relevant signals (lexical negativity, emphatic punctuation, capitalization, negation/intensifier density) that give genuine axes to model negative satisfaction. Values are mechanically countable features and align well with the source review text across samples, with no invented facts. The main weaknesses are that a couple of columns (exclamation, caps) are fairly generic text-surface features and the negation/intensifier count is somewhat non-directional, but none fail the necessary conditions."
}

